import os
import subprocess
import sys
import tempfile
import unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")

SALES = "city,year,qty\nLeeds,2020,3\nYork,2020,2.50\nLeeds,2021,4\nLeeds,2020,+1\n"
USAGE = "tabula: usage: tabula pivot FILE ROW COLUMN VALUE\n"
NO_ZIP = "tabula: t.csv: no column 'zip' (columns: city, year, qty)\n"


def run_cli(*argv, files=None, raw=None):
    with tempfile.TemporaryDirectory() as d:
        for name, text in (files or {"t.csv": SALES}).items():
            with open(os.path.join(d, name), "wb") as fh:
                fh.write(text.encode("utf-8") if raw is None else raw)
        env = dict(os.environ, PYTHONPATH=ROOT)
        p = subprocess.run([sys.executable, "-m", "tabula"] + list(argv), cwd=d, env=env,
                           capture_output=True, text=True, encoding="utf-8")
        return p.returncode, p.stdout, p.stderr


class PivotTests(unittest.TestCase):
    def check(self, argv, status, out="", err="", files=None, raw=None):
        code, stdout, stderr = run_cli(*argv, files=files, raw=raw)
        self.assertEqual((code, stdout, stderr), (status, out, err), argv)

    def test_cells(self):
        big = "1" + "0" * 5000
        cases = [
            (SALES, ("city", "year", "qty"), "city,2020,2021\nLeeds,4,4\nYork,2.50,0\n"),  # sums; absent pair is 0
            (SALES, ("year", "city", "qty"), "year,Leeds,York\n2020,4,2.50\n2021,4,0\n"),
            ("r,c,v\n1,x,3\n2,x,4\n", ("r", "c", "r"), "r,x\n1,1\n2,2\n"),  # VALUE may be the ROW column
            ("r,c,v\n1,x,3\n1,y,4\n", ("r", "c", "r"), "r,x,y\n1,1,1\n"),
            ("r,c,v\nb,y,1\na,x,2\nb,x,3\n", ("r", "c", "v"), "r,y,x\nb,1,3\na,0,2\n"),  # order of first appearance
            ("r,c,v\na,x,1\na,x,2\n", ("r", "c", "v"), "r,x\na,3\n"),
            ("r,c,v\na,x,0.1\na,x,0.2\na,x,-0.3\n", ("r", "c", "v"), "r,x\na,0.0\n"),  # exact, not floating point
            ("r,c,v\na,x,-1\na,x,1\n", ("r", "c", "v"), "r,x\na,0\n"),  # no negative zero
            ("r,c,v\na,x,+10.50\n", ("r", "c", "v"), "r,x\na,10.50\n"),  # no plus sign, 10.50 stays
            ("r,c,v\na,x, 7 \n", ("r", "c", "v"), "r,x\na,7\n"),
            ("r,c,v\n,x,1\n,y,2\nz,x,3\n", ("r", "c", "v"), "r,x,y\n,1,2\nz,3,0\n"),  # empty ROW value is a key
            ("r,c,v\na,x,1\nA,X,2\n", ("r", "c", "v"), "r,x,X\na,1,0\nA,0,2\n"),  # exact text
            ("r,c,v\na,x,1\na, x,2\n", ("r", "c", "v"), "r,x, x\na,1,2\n"),
